import { ApolloServer, gql } from 'apollo-server-express';
import express from 'express';
import multer from 'multer';
import { readFileSync } from 'fs';
import dns from 'dns/promises';

const upload = multer({ dest: '/tmp/uploads/', limits: { fileSize: 1024 * 50 } });

interface DnsRecord {
  hostname: string;
  recordType: string;
  ttl: number;
  priority?: number;
}

function parseDnsZoneFile(content: string): DnsRecord[] {
  const records: DnsRecord[] = [];
  const lines = content.split('\n').filter(l => l.trim() && !l.startsWith(';'));
  for (const line of lines) {
    const parts = line.split(/\s+/);
    if (parts.length >= 3) {
      records.push({
        hostname: parts[0],
        recordType: parts[1].toUpperCase(),
        ttl: parseInt(parts[2]) || 300,
        priority: parts.length > 3 ? parseInt(parts[3]) : undefined
      });
    }
  }
  return records;
}

function buildResolverQuery(records: DnsRecord[], filterType?: string): string {
  const conditions: string[] = [];
  for (const record of records) {
    if (filterType && record.recordType !== filterType) continue;
    conditions.push(`hostname: \"${record.hostname}\"`);
  }
  return conditions.join(', ');
}

function constructGraphQLQuery(filterExpression: string, userId: string): string {
  const sanitizedUserId = userId.replace(/[^a-zA-Z0-9_-]/g, '');
  const query = `{
    dnsRecords(filter: { ${filterExpression}, owner: \"${sanitizedUserId}\" }) {
      id
      hostname
      recordType
      ttl
      createdAt
    }
  }`;
  return query;
}

async function executeInternalQuery(query: string): Promise<any> {
  // Simulated internal GraphQL endpoint execution
  console.log('Executing query:', query);
  return { data: { dnsRecords: [] } };
}

const typeDefs = gql`
  type DnsRecord {
    id: ID!
    hostname: String!
    recordType: String!
    ttl: Int!
    priority: Int
    createdAt: String!
  }

  type UploadResult {
    success: Boolean!
    recordCount: Int!
    records: [DnsRecord!]!
  }

  type Query {
    health: String!
  }

  type Mutation {
    uploadZoneFile(userId: String!): UploadResult!
  }
`;

const resolvers = {
  Query: {
    health: () => 'OK'
  },
  Mutation: {
    uploadZoneFile: async (_: any, { userId }: { userId: string }, context: any) => {
      if (!context.req.file) {
        throw new Error('No file uploaded');
      }
      const content = readFileSync(context.req.file.path, 'utf-8');
      const records = parseDnsZoneFile(content);

      if (records.length === 0) {
        return { success: false, recordCount: 0, records: [] };
      }

      const filterExpr = buildResolverQuery(records, 'A');
      const internalQuery = constructGraphQLQuery(filterExpr, userId);
      const result = await executeInternalQuery(internalQuery);

      return {
        success: true,
        recordCount: records.length,
        records: result.data.dnsRecords
      };
    }
  }
};

const app = express();

app.post('/upload', upload.single('zonefile'), (req, res, next) => {
  req.body.file = req.file;
  next();
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: ({ req }) => ({ req })
});

server.start().then(() => {
  server.applyMiddleware({ app });
  app.listen(4000, () => console.log('Server running on port 4000'));
});

export { parseDnsZoneFile, buildResolverQuery, constructGraphQLQuery };
